input.command:
cat > tests/deliver_test.sh <<'EOF'
#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
# ADR-0009: 4 attempts, waits 3^i (3, 9, 27 s)
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
# runbook key RELAY_ATTEMPTS raises the count; waits keep the progression
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS"; fail=1; }
# the removed key RELAY_RETRY_MAX (CHANGELOG 1.9.0) is not read
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan RETRY_MAX ignored"; fail=1; }
[ "$(RELAY_SLEEP=echo bash bin/deliver false | grep -c '^wait')" = 3 ] || { echo "three waits"; fail=1; }
exit $fail
EOF
echo "--- before fix:"; bash tests/deliver_test.sh
sed -i '10,11c\# Retry schedule for webhook delivery (ADR-0009).\n# Attempts: RELAY_ATTEMPTS (default 4). Wait before attempt i+1 is 3^i seconds (3, 9, 27).' lib/delivery/retry.sh
sed -i 's/^RELAY_ATTEMPTS_DEFAULT=3/RELAY_ATTEMPTS_DEFAULT=4/; s/^RELAY_WAIT_BASE=2/RELAY_WAIT_BASE=3/; s/^RELAY_WAIT_FIRST=1/RELAY_WAIT_FIRST=3/; s/\${RELAY_RETRY_MAX:-/${RELAY_ATTEMPTS:-/' lib/delivery/retry.sh
sed -i 's/^3 attempts with doubling.*/Superseded by ADR-0009: 4 attempts, waits 3, 9, 27 s. The count can be raised with RELAY_ATTEMPTS (docs\/runbook.md, "Slow endpoints")./; s/; is 7 s enough?/; answered in ADR-0009 (39 s budget)./' docs/design/delivery.md
sed -i '0,/^## 3.4.1/s//## Unreleased\n\n- fix: deliver follows ADR-0009 (4 attempts, waits 3\/9\/27 s) and reads the count from `RELAY_ATTEMPTS`; `RELAY_RETRY_MAX` stays unread (RLY-731)\n\n## 3.4.1/' CHANGELOG.md
cat -n lib/delivery/retry.sh; echo "--- after:"; bash tests/deliver_test.sh && bash scripts/verify.sh; git status --short
